5,-1,-1,-1,0],["魔法灵氲","魔法灵氲",5,1,1,-1,-1,-1,0],["魔法警报","魔法警报",0,1,1,-1,-1,-1,0],["魔法飞弹","魔法飞弹",4,1,1,1,-1,-1,0],["魔绳术","魔绳术",7,2,2,-1,-1,-1,0],["魔鬼圈套","魔鬼圈套",0,5,5,-1,-1,-1,2],["魔魂壶","魔魂壶",6,5,5,-1,5,5,0],["鲜活外观","鲜活外观",5,3,3,-1,-1,-1,1],["鲜美血肉","鲜美血肉",7,6,6,-1,-1,-1,1],["鲜肉伪装","鲜肉伪装",7,2,2,-1,2,2,1],["鲜血之印","鲜血之印",7,2,2,-1,-1,-1,1],["鳞刺","鳞刺",7,2,2,-1,2,2,1],["鸟之歌","鸟之歌",1,1,1,-1,-1,-1,1],["鸠占鹊巢","鸠占鹊巢",6,9,9,-1,-1,-1,1],["鸿运当头","鸿运当头",4,-1,-1,-1,2,2,1],["鹰之威仪","鹰之威仪",7,2,2,-1,2,2,0],["黄衣之印","黄衣之印",3,9,9,-1,-1,-1,2],["黄金假象","黄金假象",7,3,3,-1,-1,-1,2],["黏土肌肤","黏土肌肤",0,3,3,3,3,3,2],["黏性唾液","黏性唾液",1,1,1,-1,1,1,1],["黑斑","黑斑",6,5,5,-1,-1,-1,2],["黑暗帷幕","黑暗帷幕",4,5,5,-1,-1,-1,2],["黑暗术","黑暗术",4,2,2,2,-1,-1,0],["黑暗穹顶","黑暗穹顶",0,5,5,-1,3,3,2],["黑暗耳语","黑暗耳语",5,2,2,-1,-1,-1,1],["黑暗视觉(法术)","黑暗视觉",7,2,2,-1,2,2,0],["黑曜之流","黑曜之流",7,4,4,-1,-1,-1,1],["黑盲矢","黑盲矢",1,3,3,3,-1,-1,1],["黑触手","黑触手",1,4,4,4,-1,-1,0],["黑鸦天翔","黑鸦天翔",7,2,2,2,-1,-1,2],["黯光术","黯光术",4,3,3,-1,-1,-1,2],["鼓舞毒药","鼓舞毒药",7,-1,-1,-1,2,2,2],["齿轮之墙","齿轮之墙",1,5,5,-1,-1,-1,2],["龙之声","龙之声",7,2,2,-1,2,2,2],["龙威术","龙威术",3,3,3,-1,-1,-1,2],["龙息术","龙息术",4,4,4,4,4,4,1],["龙龟之壳","龙龟之壳",0,3,3,-1,3,3,2]],"r":[["创伤之书","s",5,365,"创伤之浪","你可以将法术发挥至极限，但是这么做同样会伤害到你。当你施放法师的塑能法术时能以[[自由动作]]消耗该增益效果。当你这么做时，可以视同使用“[[法术极效]]”[[超魔专长]]施放该法术一般，但是你会受到 {1d4×你要极效超魔的法术环位} 点伤害。由此受到的伤害无法以任何方式减免。",4],["康斯坦斯．英伏里克斯的实验室日志","f",5,375,"炼金防护术","这本日志赋予你的炼金知识能够从毒素与炼金物品中保护你。当你进行对抗毒素或炼金物品造成的豁免，并且在进行豁免检定之前，能够以[[直觉动作]]消耗此增益效果。你在该次检定中获得+4加值。",-1],["墓穴之书","s",6,450,"墓穴之息","以[[迅捷动作]]并花费增益的效果，你可以吐出15尺锥形的腐败恶臭。在锥形范围内的生物必须成功通过强韧豁免检定 (DC为 {10+你所具有的准备施法职业的最高CL}), 否则会[[恶心]]1轮。这会消耗掉增益。在该增益被消耗之后，你的交涉与隐匿检定会在你再次准备法术之前受到-4减值。",6],["辉煌之眼密卷","s",7,700,"辉煌之眼","当施放幻术系法术时，你获得扩展视域。当你施放幻术系法术时，能以自由动作消耗增益的效果。你会获得60尺黑暗视觉，并在对抗幻术使自身不相信幻象的豁免检定中获得+4加值，这些效果持续1分钟。",5],["变化师之书","s",8,800,"防御形态","当变为其他形态时，你可以增强你的防御力。当你施放变化系法术，并且该法术的施法距离为个人时，能以自由动作消耗该增益的效果。只要你还受到该法术的影响，你就会在该法术的持续时间内获得+2天生护甲加值。",7],["鲁尔．萨文的熟练学徒之书","s",9,1125,"鲁尔．萨文之眼","你能使用鲁尔．萨文完善的戏法察觉[[隐形]]生物。以迅捷动作消耗该增益的效果。你能在1轮内获得‘识破隐形’的效果。",2],["兽性日志","f",10,1250,"兽化混合物","这本日志会赋予你制作极端强效的兽性[[突变药剂]]的能力。当你饮用突变药剂时消耗该增益。突变药剂会使你选择的属性获得+6炼金加值，而非原本的+4；当突变药剂生效时，你的所有心智属性受到-2减值 (智力，感知与魅力)。",-1],["极寒之嚎","s",11,1650,"白霜之咬","你能使法术塑造出几乎无人能承受的刺骨之寒。当你施放带有 [冷] 描述符的法术时，能以自由动作消耗该增益。该法术所造成的任何伤害均会忽略所有寒冷抗力, 但是无法忽略免疫寒冷。",4],["远见者塔恩尼斯的智慧","s",12,1800,"强壮召唤","你所召唤的生物的防御会获得短时间的强化。当你施放一个咒法系 (召唤) 的法师法术时，能以自由动作消耗该增益的效果。你使用该法术所召唤的生物会获得等同于你CL的临时HP，并且只要被召唤的生物还留有1点由此获得的临时HP，它的豁免检定就会得到+2环境加值。",1],["探寻永恒","s",13,1920,"行旅智者","没有什么东西能像魔法书一样增强记忆力。与其他增益不同，你不需要去消耗掉它。直至你再次准备法术为止，你的知识 (地理) 被视为已受训。如果你已经在知识 (地理) 上投入技能点数，那么你会在该技能的检定中获得+2环境加值。",2],["守护者密卷","s",15,3000,"守护者技法","你尝试以充满力量的短句挫败一次攻击。当一名不死生物或者异界生物的攻击命中你时，你能以直觉动作消耗增益的效果。攻击的生物必须重投攻击检定，并使用第二次检定的结果，即使它比前一次更低。",0],["影之谜","s",16,3200,"影之学识","这本书中的知识就像影界本身一样附着在你的意识之上。与其他增益不同，你无须消耗该增益。直至你下次准备法术为止，只要你所进行的检定是关于影界的地理与居民，那么的所有知识技能均被视为已经受训。如果你已经在适用的知识技能中投入技能点，那么你会在这次检定中获得+2环境加值。",5],["鲁尔．萨文的大师之书","s",17,3825,"强效鲁尔．萨文之眼","这个被强化的增益能使你看到隐形的生物。你能够以迅捷动作激活增益的效果，以此获得至多10轮‘识破隐形’的效果。这些轮数不必连续，但是你每次激活增益的效果时都需要耗费迅捷动作。当10轮识破隐形全被用光，或者你下一次准备法师法术时，增益的效果才会被消耗。",2],["誓缚手册","s",18,4050,"应急复还术","你不能使用动作消耗该增益。当受到该增益影响后，你的HP第一次降至0或更低时，你会立即恢复2d6点生命值。如果这足以将你的生命值提升至0或更高，你就不会[[失去意识]]。",1],["皮舞者丛书","s",19,4275,"御法增益","你能够产生一波快速的奥能爆发，这能够防御一次法术攻击。当你被接触法术或类法术能力作为目标时，能够以直觉动作消耗该增益的效果，使你在对抗这次[[接触攻击]]时AC获得+4偏斜加值。",-1],["大师吉波尔的配方集","f",20,4500,"自发爆弹","在用炸弹上，你总是有出人意料的花招。每日1次以迅捷动作，你能够将一个你有资格获得的[[科研发现]] (但是你还未获得) 应用到一个炼金炸弹上。这不会允许你在一个炼金炸弹上叠加应用无法共同使用的科研发现。",-1],["语思权柄","s",20,4590,"诅咒之名","当你使用这本书准备好法术之后，将一个生物的正式姓名 写到这本书的名单中。当你距离被指定的生物30尺内时，能够以迅捷动作叫他的名字并赋予他诅咒之名。这会消耗掉增益的效果。目标所有攻击检定受到-2减值，所有对你的攻击检定受到-4减值，持续1分钟。当你激活该诅咒后，这个名字会在书中被划掉。该名生物无法再次成为来源于你的诅咒之名的目标。对同一生物的多个诅咒之名的减值不会叠加。",3],["尼扎姆的治疗法","f",3,65,"灌输治愈","每当你饮用一个炼金术师炼成的咒法系法术时，你可以以一个迅捷动作消耗该增益。如果你这样做，你可以治愈1点伤害并忽略[[疲乏]]效果1轮。",-1],["剑侠文选","s",3,150,"武器屏蔽","你的法术会给武器注入保护魔法。当你施展一个防护系法术时，可以以一个迅捷动作直觉动作消耗该增益。如果你这样做，你挥舞的一把武器会使你的AC获得相当于1+1/2该法术环位的盾牌加值，持续1轮。",-1],["贾特比的智慧（三勇士版）","s",5,500,"贾特比之眼","本法术书中的数个故事提供了一些方法用来将那些你已有的信息推断那些你没有经过验证手法问题的答案。当你施展一个预言系法术时，消耗该增益以增加该法术的施法者等级至+2。",2],["艾拉格斯的老炮手册","s",7,525,"躲避法术","当你施展一个变化系法术时，你可以以一个迅捷动作消耗该增益，你的AC在等同于在该法术环级的回合数内获得+1闪避加值",-1],["迦尔特人的食谱","f",8,600,"娴熟爆发","当你投掷一枚炸弹时可以以一个直觉动作消耗该增益向该区域增加3个5尺方格以塑造爆炸，只要这些空间与炸弹的正常作用区域相邻。",-1],["大指南选集","s",6,300,"荣耀利刃","当你使用一把剑（包括由法术创造的类剑效果比如[[灵能武器]]，只要它们需要攻击骰）攻击时，你可以以一个自由动作消耗该增益并花费一个已准备好的法术或是法术位。如果你这样做，你在攻击骰上获得等同于被花费的已准备法术或法术位环级的洞察加值。",-1],["箭歌的哀伤","s",3,1000,"骚扰大师","箭歌对于不完美施法和魔法失败的宣言为中断施法提供了额外的领悟。与其他的增益不同，你不需要消耗这个增益。在你再次准备法术之前，当你伤害一个敌人或该敌人对你的一个法术的豁免检定失败时，该敌人在1轮内的所有专注检定会受到-2的罚值。",-1],["窥探之眼","s",7,260,"敏锐洞察","你可以在单一的[[察觉]]或[[察言观色]]检定中消耗该增益获得+2洞察加值。",-1],["冷嘲热讽","s",6,375,"洗脑","你结合了魔法和技术来巧妙地操纵你的目标。当你对一个你已经成功通过[[唬骗]]，[[交涉]]，[[知识]]或察言观色检定对抗的生物施展一个法术时，你可以消耗该增益。你施展的法术+1施法者等级而且它的豁免DC增加1。",-1],["岩石守护之卷","s",17,4000,"石之守护者","岩石守护之卷彻底地涵盖了洞穴和山脉（尤其是五王山脉）的地理情况，并且对这些地形是如何形成的提供了骇人的见解。该增益不会被消耗，但是你在知识（地城），知识（地理）和知识（自然）检定以及在丘陵，山岳，和地底地形中的[[生存]]检定获得+1洞察加值。此外，当你在完全由石头制成的物体上施放修复术、完全修复术或高等完全修复术（译注：高等完全修复术出自《[[科技指南]]》）时，在该物体恢复的生命值上增加1d6。这些增益持续到你下次重新获得法术位或准备法术。",0],["塞鲁西安法典","s",11,4700,"持久变化","你的法术抵御着尝试恢复那些你改变事物的现实。当施展一个变化系法术时，你可以消耗该增益获得[[法术延时]]专长的收益。这也会增加解除该法术4点的DC（通过解除魔法或类似能力）。此增益不会增加你法术的法术环位或施法时间。",2],["贾特比的智慧（九勇士版）","s",17,25000,"贾特比的秘密","这个版本的贾特比的智慧包含了一些据说是老巫师贾特比自己写的独特的仪式和哲学笔记。这些秘密允许你准备下列法术之一作为一个比德鲁伊法术环位高1级的奥术法术：树肤术，[[召雷术]]，[[循环转生术]]（AA），[[纠缠术]]，[[丛林之友]]（UC），[[次等复原术]]，[[植物滋长]]，[[动物交谈]]以及[[植物交谈]]。根据GM的决定，额外的德鲁伊法术列表中的6级或更低级别的法术可以通过本书的特定副本的预置仪式获得（这将使这本法术书的价格增加两倍于向这本法术书添加相同环位等级的法师法术的成本）。",2],["财富符文","s",18,5000,"改变魔法","即便是魔法的本质也会受到你强大的变化术影响。你可以以一个迅捷动作消耗该增益来宣布一个你正在施展的非变化系法术为“被改变魔法”。该法术成为了一个变化系效果，并从任何影响你变化系法术的能力或专长中受益，并且可以应用到你施放的法术上（比如[[法术专攻]]）。",7]]}]=====]